$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$stage='D:\Claude\swiftright\.work\sr0-r12-workload-v1';$runs=Join-Path $stage 'incremental-runs'
$dirs=@(Get-ChildItem -LiteralPath $runs -Directory);if($dirs.Count -gt 8){throw 'Incremental run inventory bound'}
$rows=@();foreach($d in $dirs){$files=@();foreach($path in @((Join-Path $d.FullName 'trials\edit-1.stdout.txt'),(Join-Path $d.FullName 'trials\edit-1.stderr.txt'),(Join-Path $d.FullName 'held-mutation-receipt.json'))){if(Test-Path -LiteralPath $path -PathType Leaf){$i=Get-Item -LiteralPath $path;if($i.Length -gt 1MB -or ($i.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Trial read bound'};$files+=[ordered]@{path=$path;bytes=$i.Length;sha256=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant();text=[IO.File]::ReadAllText($path)}}};$rows+=[ordered]@{path=$d.FullName;files=$files}}
$artifacts=@();foreach($path in @((Join-Path $stage 'scratch\out\Products\Release-windows-x86_64\WorkloadWin.exe'),(Join-Path $stage 'scratch\out\Products\Release-windows-x86_64\swiftright_render.dll'),(Join-Path $stage 'src\probes\sr0-b\workload\Sources\WorkloadCore\WorkloadScreen.swift'))){$i=Get-Item -LiteralPath $path;if($i.Length -gt 32MB -or ($i.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Artifact read bound'};$artifacts+=[ordered]@{path=$path;sha256=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant();bytes=$i.Length}}
$live=@(Get-Process swift,swiftc,swift-build,swift-frontend,clang -ErrorAction SilentlyContinue|ForEach-Object{[ordered]@{pid=$_.Id;name=$_.ProcessName;rssBytes=$_.WorkingSet64;session=$_.SessionId}})
[ordered]@{kind='root-sr0-v7-incremental-failure-read-v1';runs=$rows;artifacts=$artifacts;liveCompilers=$live;nativeActions=0;lockActions=0}|ConvertTo-Json -Depth 12
